MWE:
```C
#include <openssl/ec.h>
#include <assert.h>

int main(int argc, char **argv) {
    EC_GROUP *group = NULL;
    FILE *fp = NULL;

    assert((fp = fopen("params.der", "rb")) != NULL);
    assert((group = d2i_ECPKParameters_fp(fp, NULL)) != NULL);
    fclose(fp);
    EC_GROUP_free(group);

    return 0;
}
```

